WITH address_store_map AS (SELECT DISTINCT ss.ss_addr_sk AS address_sk, ss.ss_store_sk AS store_sk FROM store_sales ss), returns_enriched AS (SELECT asm.store_sk, r.r_reason_desc, SUM(wr.wr_return_amt_inc_tax) AS total_return_amt, COUNT(DISTINCT wr.wr_order_number) AS return_orders, COUNT(*) AS return_rows FROM web_returns wr JOIN customer_address ca ON wr.wr_refunded_addr_sk = ca.ca_address_sk JOIN address_store_map asm ON ca.ca_address_sk = asm.address_sk JOIN reason r ON wr.wr_reason_sk = r.r_reason_sk WHERE wr.wr_returned_date_sk BETWEEN 2450815 AND 2450996 GROUP BY asm.store_sk, r.r_reason_desc), top_reason AS (SELECT store_sk, r_reason_desc, total_return_amt, ROW_NUMBER() OVER (PARTITION BY store_sk ORDER BY total_return_amt DESC) AS rn FROM returns_enriched), store_sales_agg AS (SELECT s.s_store_sk, s.s_store_name, SUM(ss.ss_ext_sales_price) AS total_sales, SUM(ss.ss_net_profit) AS total_net_profit, COUNT(DISTINCT ss.ss_ticket_number) AS num_transactions FROM store_sales ss JOIN store s ON ss.ss_store_sk = s.s_store_sk WHERE ss.ss_sold_date_sk BETWEEN 2450815 AND 2450996 GROUP BY s.s_store_sk, s.s_store_name), store_returns_agg AS (SELECT asm.store_sk, SUM(wr.wr_return_amt_inc_tax) AS total_return_amt, COUNT(DISTINCT wr.wr_order_number) AS total_return_orders FROM web_returns wr JOIN customer_address ca ON wr.wr_refunded_addr_sk = ca.ca_address_sk JOIN address_store_map asm ON ca.ca_address_sk = asm.address_sk WHERE wr.wr_returned_date_sk BETWEEN 2450815 AND 2450996 GROUP BY asm.store_sk) SELECT s.s_store_name, s.total_sales, COALESCE(r.total_return_amt, 0) AS total_return_amt, s.total_net_profit - COALESCE(r.total_return_amt, 0) AS net_profit_adj, CASE WHEN s.total_sales > 0 THEN COALESCE(r.total_return_amt, 0) / s.total_sales ELSE 0 END AS return_to_sales_ratio, s.num_transactions, COALESCE(r.total_return_orders, 0) AS total_return_orders, tr.r_reason_desc AS top_return_reason, tr.total_return_amt AS top_reason_return_amt FROM store_sales_agg s LEFT JOIN store_returns_agg r ON s.s_store_sk = r.store_sk LEFT JOIN (SELECT store_sk, r_reason_desc, total_return_amt FROM top_reason WHERE rn = 1) tr ON s.s_store_sk = tr.store_sk WHERE s.total_sales > 10000 ORDER BY net_profit_adj DESC LIMIT 10
